<script setup>
import { Bike, CalendarCheck2, Coins, TrendingUp } from '@lucide/vue';
import { onMounted, ref } from 'vue';
import { api } from '../../services/api.js';
const stats = ref(null); const loading = ref(true);
onMounted(async () => { try { const response = await api.get('/drivers/earnings'); stats.value = response.data.data; } finally { loading.value = false; } });
const peso = (value) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP', maximumFractionDigits: 0 }).format(value ?? 0);
</script>
<template><section class="page earnings"><div class="page-header"><div><span class="eyebrow">Your performance</span><h1 class="page-title">Earnings</h1><p class="muted">Completed rides recorded by RYDORA.</p></div></div><div v-if="loading" class="skeleton" style="height:300px"></div><template v-else><div class="hero"><span><TrendingUp :size="25" /></span><small>Total recorded earnings</small><strong>{{ peso(stats.totalEarnings) }}</strong><p>From {{ stats.totalCompletedBookings }} completed passenger drop-off{{ stats.totalCompletedBookings === 1 ? '' : 's' }}</p></div><div class="stats"><article class="card"><Coins /><span>Today’s earnings</span><strong>{{ peso(stats.todayEarnings) }}</strong></article><article class="card"><CalendarCheck2 /><span>Completed today</span><strong>{{ stats.todayCompletedBookings }}</strong></article><article class="card"><Bike /><span>All completed</span><strong>{{ stats.totalCompletedBookings }}</strong></article></div></template></section></template>
<style scoped>.earnings{max-width:900px}.hero{display:grid;justify-items:center;padding:32px;border-radius:23px;color:white;background:linear-gradient(145deg,#064e3b,#059669);box-shadow:var(--shadow-float);text-align:center}.hero>span{display:grid;width:54px;height:54px;place-items:center;margin-bottom:15px;border-radius:17px;background:rgb(255 255 255/.15)}.hero small{color:rgb(255 255 255/.72)}.hero strong{margin:8px 0;font-size:2.5rem;letter-spacing:-.05em}.hero p{margin:0;color:rgb(255 255 255/.72);font-size:.75rem}.stats{display:grid;gap:13px;margin-top:18px}.stats article{display:grid;grid-template-columns:auto 1fr;gap:5px 12px;padding:17px}.stats svg{grid-row:1/3;color:var(--color-primary)}.stats span{color:var(--color-text-soft);font-size:.72rem}.stats strong{font-size:1.05rem}@media(min-width:650px){.stats{grid-template-columns:repeat(3,1fr)}}</style>

